package com.bank.traffic;

import java.util.*;
import java.util.logging.Logger;

// Walks the request path and reports the FIRST broken layer with a fix.
public class TrafficPathChecker {
    private static final Logger log = Logger.getLogger(TrafficPathChecker.class.getName());

    // returns the chosen Pod IP if traffic can flow, else null.
    public String walk(List<PodBackend> pods, ServiceSpec svc, String ingressBackendSvc,
                       String actualSvcName, boolean networkPolicyAllows, boolean lbHealthy) {

        // Layer 1: readiness
        List<PodBackend> ready = new ArrayList<>();
        for (PodBackend p : pods) if (p.ready) ready.add(p);
        if (ready.isEmpty()) {
            log.severe("L1 readiness: all pods 0/1 Ready — excluded from Service");
            log.info("FIX: correct the readiness probe path/port so it returns 200");
            return null;
        }
        // Layer 2: Service selector -> endpoints
        List<PodBackend> endpoints = new ArrayList<>();
        for (PodBackend p : ready) if (p.labels.entrySet().containsAll(svc.selector.entrySet())) endpoints.add(p);
        if (endpoints.isEmpty()) {
            log.severe("L2 endpoints: EMPTY — Service selector does not match Pod labels");
            log.info("FIX: align Service selector with Pod labels (kubectl describe svc / get endpointslices)");
            return null;
        }
        // Layer 2b: port mapping
        PodBackend chosen = endpoints.get(0);
        if (svc.targetPort != chosen.listenPort) {
            log.severe("L2b port: targetPort " + svc.targetPort + " != container listen " + chosen.listenPort);
            log.info("FIX: set Service targetPort to the real container port");
            return null;
        }
        // Layer 3: Ingress backend
        if (!ingressBackendSvc.equals(actualSvcName)) {
            log.severe("L3 ingress: backend '" + ingressBackendSvc + "' != service '" + actualSvcName + "'");
            log.info("FIX: point Ingress backend at the correct Service + port");
            return null;
        }
        // Layer 4: NetworkPolicy
        if (!networkPolicyAllows) {
            log.severe("L4 networkpolicy: ingress from controller BLOCKED by default-deny");
            log.info("FIX: add an allow-ingress rule from the ingress-controller namespace/labels");
            return null;
        }
        // Layer 5: LB health check
        if (!lbHealthy) {
            log.severe("L5 LB: target group health check FAILING -> backend marked unhealthy");
            log.info("FIX: point LB health check at a path that returns 200");
            return null;
        }
        log.info("all layers healthy -> traffic reaches pod " + chosen.ip);
        return chosen.ip;
    }
}
