package com.bank.traffic;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class TrafficTriageDemo {
    private static final Logger log = Logger.getLogger(TrafficTriageDemo.class.getName());
    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler(); h.setFormatter(new BankLogFormatter()); h.setLevel(Level.ALL);
        Logger root = Logger.getLogger(""); root.addHandler(h); root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000"));
        Account priya  = new Account("CUR3001", "Priya Sharma", new BigDecimal("250000"));
        TrafficPathChecker checker = new TrafficPathChecker();

        // BROKEN: Pod labels app=transfer-svc but Service selector app=transfer
        PodBackend running = new PodBackend("10.244.1.9", Map.of("app","transfer-svc"), true, 8080);
        ServiceSpec svc = new ServiceSpec(Map.of("app","transfer"), 80, 8080);
        String ip = checker.walk(List.of(running), svc, "transfer-service", "transfer-service", true, true);
        log.info("broken selector result: " + ip);

        // FIXED: selector matches labels; all layers healthy
        ServiceSpec fixed = new ServiceSpec(Map.of("app","transfer-svc"), 80, 8080);
        String ip2 = checker.walk(List.of(running), fixed, "transfer-service", "transfer-service", true, true);
        if (ip2 != null) {
            rajesh.debit(new BigDecimal("50000")); priya.credit(new BigDecimal("50000"));
            log.info("transfer SAV2001->CUR3001 Rs.50000 reached " + ip2 + " SUCCESS");
        }
    }
}
