package com.bank.traffic;

import java.time.*;
import java.time.format.DateTimeFormatter;
import java.util.logging.*;

public class BankLogFormatter extends Formatter {
    private static final DateTimeFormatter FMT = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss.SSS");
    @Override public String format(LogRecord r) {
        String ts = LocalDateTime.ofInstant(Instant.ofEpochMilli(r.getMillis()), ZoneId.systemDefault()).format(FMT);
        return String.format("%s [%s] %s%n", ts, r.getLevel(), formatMessage(r));
    }
}
