metadata: { name: transfer-service }
spec:
  selector: { app: transfer-svc }   # align with Pod labels!
  ports: [{ port: 80, targetPort: 8080 }]   # targetPort = container listen port
---
# k8s/ingress.yaml — backend must name the correct Service + port
apiVersion: networking.k8s.io/v1
kind: Ingress
metadata: { name: nbi-ingress }
spec:
  rules:
    - host: api.nbi.com
      http:
        paths:
          - path: /transfers
            pathType: Prefix
            backend: { service: { name: transfer-service, port: { number: 80 } } }
